import{_ as s}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as l,a as d,b as c}from"./chunks/logo_linux_foundation.dU8ZK45C.js";import{u as h,o as r,c as t,al as a,k as u,e as p,j as o,t as m}from"./chunks/framework.7vp1BMOE.js";const f={key:0},w=JSON.parse('{"title":"PX4 Autopilot User Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),g={name:"en/index.md"},k=Object.assign(g,{setup(b){const{site:i}=h();return(n,e)=>(r(),t("div",null,[e[1]||(e[1]=a('<h1 id="px4-autopilot-user-guide" tabindex="-1">PX4 Autopilot User Guide <a class="header-anchor" href="#px4-autopilot-user-guide" aria-label="Permalink to &quot;PX4 Autopilot User Guide&quot;">​</a></h1><p><a href="https://github.com/PX4/PX4-Autopilot/releases" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/release-main-blue.svg" alt="Releases"></a> <a href="https://discuss.px4.io//" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/discuss-px4-ff69b4.svg" alt="Discuss"></a> <a href="https://discord.com/invite/dronecode" target="_blank" rel="noreferrer"><img src="https://discordapp.com/api/guilds/1022170275984457759/widget.png?style=shield" alt="Discord"></a></p><p>PX4 is an open-source autopilot for drones and autonomous vehicles. It runs on multirotors, fixed-wing, VTOL, helicopters, rovers, and more. This guide covers everything from assembly and configuration to flight operations and development.</p>',3)),u(i).title=="PX4 Guide (main)"?(r(),t("div",f,[...e[0]||(e[0]=[a('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This guide is for the <em>development</em> version of PX4 (<code>main</code> branch). Use the <strong>Version</strong> selector to find the current <em>stable</em> version.</p><p>Documented changes since the stable release are captured in the evolving <a href="./releases/main">release note</a>.</p></div>',1)])])):p("",!0),e[2]||(e[2]=a('<h2 id="try-px4" tabindex="-1">Try PX4 <a class="header-anchor" href="#try-px4" aria-label="Permalink to &quot;Try PX4&quot;">​</a></h2><p>No hardware needed. Run PX4 in simulation with a single command using <a href="./simulation/px4_simulation_quickstart">Docker or a .deb package</a>. Connect <a href="https://qgroundcontrol.com" target="_blank" rel="noreferrer">QGroundControl</a>, <a href="https://mavsdk.mavlink.io/" target="_blank" rel="noreferrer">MAVSDK</a>, or <a href="./ros2/">ROS 2</a> and start flying immediately.</p><h2 id="for-developers" tabindex="-1">For Developers <a class="header-anchor" href="#for-developers" aria-label="Permalink to &quot;For Developers&quot;">​</a></h2><p>Want to modify PX4 or build from source? Start with the <a href="./development/development">Development Guide</a>: set up your <a href="./dev_setup/dev_env">dev environment</a>, <a href="./dev_setup/building_px4">build the code</a>, and run <a href="./simulation/">SITL simulation</a>.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Start with <a href="./getting_started/px4_basic_concepts">Basic Concepts</a> for an overview of the flight stack, flight modes, safety features, and supported hardware.</p><h2 id="developer-kits" tabindex="-1">Developer Kits <a class="header-anchor" href="#developer-kits" aria-label="Permalink to &quot;Developer Kits&quot;">​</a></h2><p>The fastest way to get flying hardware for PX4 development. <a href="./dev_kits/">Official PX4 Developer Kits</a> ship with the latest stable PX4 pre-installed on current Pixhawk-standard hardware, need no build skills, and are certified by the PX4 team.</p><h2 id="build-a-vehicle" tabindex="-1">Build a Vehicle <a class="header-anchor" href="#build-a-vehicle" aria-label="Permalink to &quot;Build a Vehicle&quot;">​</a></h2><p>Pick your frame type: <a href="./frames_multicopter/">Multicopter</a>, <a href="./frames_plane/">Fixed-Wing</a>, <a href="./frames_vtol/">VTOL</a>, <a href="./frames_helicopter/">Helicopter</a>, or <a href="./frames_rover/">Rover</a>. Each section covers complete vehicles, kits, and DIY builds. For assembly instructions see <a href="./assembly/assembly_mc">Assembling a Multicopter</a> or the equivalent for your frame.</p><h2 id="configure-and-tune" tabindex="-1">Configure and Tune <a class="header-anchor" href="#configure-and-tune" aria-label="Permalink to &quot;Configure and Tune&quot;">​</a></h2><p>Once assembled, follow the configuration guide for your vehicle type (e.g. <a href="./config_mc/">Multicopter Configuration</a>). This covers sensor calibration, flight mode setup, and tuning.</p><h2 id="hardware" tabindex="-1">Hardware <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Hardware&quot;">​</a></h2><p>The <a href="./hardware/drone_parts">Hardware Selection &amp; Setup</a> section covers flight controllers, sensors, telemetry, RC systems, and payloads. See <a href="./payloads/">Payloads</a> for camera and delivery integrations.</p><h2 id="fly" tabindex="-1">Fly <a class="header-anchor" href="#fly" aria-label="Permalink to &quot;Fly&quot;">​</a></h2><p>Read <a href="./config/operations">Operations</a> to understand safety features and failsafe behavior before your first flight. Then see <a href="./flying/basic_flying_mc">Basic Flying (Multicopter)</a> or the equivalent for your frame type.</p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>Get help on the <a href="https://discuss.px4.io/" target="_blank" rel="noreferrer">discussion forums</a> or <a href="https://discord.com/invite/dronecode" target="_blank" rel="noreferrer">Discord</a>. See the <a href="./contribute/support">Support</a> page for diagnosing problems, reporting bugs, and joining the <a href="./contribute/dev_call">weekly dev call</a>.</p><h2 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>See the <a href="./contribute/">Contributing</a> section for code, <a href="./contribute/docs">documentation</a>, and <a href="./contribute/translation">translation</a> guidelines.</p><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>There are several <a href="./contribute/translation">translations</a> of this guide. Use the language selector in the top navigation.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>PX4 code is free to use and modify under the terms of the permissive <a href="https://opensource.org/license/BSD-3-Clause" target="_blank" rel="noreferrer">BSD 3-clause license</a>. This documentation is licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. For more information see: <a href="./contribute/licenses">Licences</a>.</p><h2 id="calendar-events" tabindex="-1">Calendar &amp; Events <a class="header-anchor" href="#calendar-events" aria-label="Permalink to &quot;Calendar &amp; Events&quot;">​</a></h2><p>The <em>Dronecode Calendar</em> shows important community events for platform users and developers. Select the links below to display the calendar in your timezone (and to add it to your own calendar):</p><ul><li><a href="https://calendar.google.com/calendar/embed?src=linuxfoundation.org_g21tvam24m7pm7jhev01bvlqh8%40group.calendar.google.com&amp;ctz=Europe%2FZurich" target="_blank" rel="noreferrer">Switzerland – Zurich</a></li><li><a href="https://calendar.google.com/calendar/embed?src=linuxfoundation.org_g21tvam24m7pm7jhev01bvlqh8%40group.calendar.google.com&amp;ctz=America%2FTijuana" target="_blank" rel="noreferrer">Pacific Time – Tijuana</a></li><li><a href="https://calendar.google.com/calendar/embed?src=linuxfoundation.org_g21tvam24m7pm7jhev01bvlqh8%40group.calendar.google.com&amp;ctz=Australia%2FSydney" target="_blank" rel="noreferrer">Australia – Melbourne/Sydney/Hobart</a></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The calendar default timezone is Central European Time (CET).</p></div>',28)),e[3]||(e[3]=o("iframe",{src:"https://calendar.google.com/calendar/embed?title=Dronecode%20Calendar&mode=WEEK&height=600&wkst=1&bgcolor=%23FFFFFF&src=linuxfoundation.org_g21tvam24m7pm7jhev01bvlqh8%40group.calendar.google.com&color=%23691426&ctz=Europe%2FZurich",style:{"border-width":"0"},width:"800",height:"600",frameborder:"0",scrolling:"no"},null,-1)),e[4]||(e[4]=a('<h3 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h3><p>The following icons used in this library are licensed separately (as shown below):</p><p><img src="'+s+'" title="Position fix required (e.g. GPS)" width="30px"> <em>placeholder</em> icon made by <a href="https://www.flaticon.com/authors/smashicons" title="Smashicons">Smashicons</a> from <a href="https://www.flaticon.com/" title="Flaticon">www.flaticon.com</a> is licensed by <a href="https://creativecommons.org/licenses/by/3.0/" title="Creative Commons BY 3.0" target="_blank">CC 3.0 BY</a>.</p><p><img src="'+l+'" title="Automatic mode" width="30px"> <em>camera-automatic-mode</em> icon made by <a href="https://www.magnific.com/" title="Magnific">Magnific (formerly Freepik)</a> from <a href="https://www.flaticon.com/" title="Flaticon">www.flaticon.com</a> is licensed by <a href="https://creativecommons.org/licenses/by/3.0/" title="Creative Commons BY 3.0" target="_blank">CC 3.0 BY</a>.</p><h2 id="governance" tabindex="-1">Governance <a class="header-anchor" href="#governance" aria-label="Permalink to &quot;Governance&quot;">​</a></h2><p>The PX4 Autopilot project is hosted by the <a href="https://dronecode.org/" target="_blank" rel="noreferrer">Dronecode Foundation</a>, a <a href="https://www.linuxfoundation.org/" target="_blank" rel="noreferrer">Linux Foundation</a> Collaborative Project. Dronecode holds all PX4 trademarks and serves as the project&#39;s legal guardian, ensuring vendor-neutral stewardship. No single company owns the name or controls the roadmap. The source code is licensed under the <a href="https://opensource.org/license/BSD-3-Clause" target="_blank" rel="noreferrer">BSD 3-Clause</a> license, so you are free to use, modify, and distribute it in your own projects.</p><p><a href="https://dronecode.org/" style="padding:20px;"><img src="'+d+'" alt="Dronecode Logo" width="140px"></a><a href="https://www.linuxfoundation.org/projects" style="padding:20px;"><img src="'+c+'" alt="Linux Foundation Logo" width="80px"></a></p><div style="padding:10px;"> </div>',8)),o("p",null,"Doc build time: "+m(n.$buildTime),1)]))}});export{w as __pageData,k as default};
